import { fail } from './result.js';
import { balanceDue } from './payments.js';
import { isValidDate, daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVAT } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Generate a report of overdue invoices.
 * @param {Array<any>} invoices - Array of invoices to filter
 * @param {string} asOf - Report date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array<any> } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  const overdue = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return { ok: true, value: overdue };
}

/**
 * Generate a VAT summary report.
 * @param {Array<any>} invoices - Array of invoices to summarize
 * @returns {Array<{ rate: number, base: number, vat: number }>} - VAT entries sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      if (!inv.lines) return;

      inv.lines.forEach((line) => {
        const rate = line.vatRate || 0;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVAT(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { base: 0, vat: 0 };
        }

        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  return Object.entries(vatMap)
    .map(([rate, { base, vat }]) => ({
      rate: parseFloat(rate),
      base,
      vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an invoice.
 * @param {any} invoice - The invoice
 * @param {string} asOf - Report date in YYYY-MM-DD format
 * @returns {{ ok: true, value: number } | { ok: false, error: string }} - Late fee in cents
 */
export function lateFee(invoice, asOf) {
  if (!isValidDate(asOf)) {
    return fail('DATE_INVALID');
  }

  if (invoice.status !== 'issued' && invoice.status !== 'partially_paid') {
    return { ok: true, value: 0 };
  }

  if (!invoice.dueDate || invoice.dueDate >= asOf) {
    return { ok: true, value: 0 };
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const feeAmount = due * 0.0004 * daysOverdue;
  const lateFeeAmount = roundCents(feeAmount);

  return { ok: true, value: lateFeeAmount };
}

